{
  "a_requests": [
    {
      "a_request": "R1",
      "b_asked": "서울시장이 등록대상 반려견의 출입을 제한한다고 지정·고시한 장소에 개를 안고 잠깐 들어가는 것이 조례상 허용되는지 여부",
      "c_basis": "DIRECT",
      "d_claims": [
        {
          "a_text": "서울시장이 지정·고시한 장소에서는 등록대상동물을 동반하고 출입하는 것이 허용되지 않습니다. 조례 제7조제2항은 등록대상동물의 소유자등이 시장이 지정·고시한 지역 또는 장소에 등록대상동물을 사육하거나 동반하고 출입을 하여서는 아니 된다고 정하고 있습니다. 개를 안고 들어가는 것도 등록대상동물을 동반하는 행위에 해당하므로 허용되지 않습니다.",
          "b_ids": "동물보호:제7조제2항, 동물보호:제2조제7호, 동물보호:제2조제2호"
        }
      ],
      "e_status": "ANSWERED"
    }
  ]
}
